examples:
local p = trx.argparse.new({ prog = "weather" })
p:positional("state", { choices = { "snow", "rain", "none" } })
local parsed = p:parse("snow")  -- { state = "snow" }

trx.console.register({
  name = "greet",
  aliases = { "hello", "hi" },
  args = function(parser)
    parser:positional("who", { help = "who to greet" })
  end,
  run = function(args)
    trx.console.log("hello " .. args.who)
  end,
})

trx.events.on_title_start(function()
  trx.log.info("the menu is up")
end)

trx.events.on_flip_effect(62, function(timer, item_num)
  trx.log.info("flipeffect 62 ran with timer " .. timer)
end)

trx.events.on_room_change(function(item, old_room, new_room)
  trx.log.info(item.object_id .. " moved to room " .. new_room)
end)

trx.events.on_finish(function(item)
  trx.log.info(item.object_id .. " finished its run")
end)

trx.events.on_enter_world(function(item)
  trx.log.info(item.object_id .. " entered the world")
end)

trx.events.on_leave_world(function(item)
  trx.log.info(item.object_id .. " left the world")
end)

trx.events.on_hit(function(item, damage)
  trx.log.info(item.object_id .. " lost " .. damage .. " hit points")
end)

trx.locale.declare({
  ["console/cmd/heal/help"] = "Heals Lara back to full health.",
  ["console/cmd/heal/success"] = "Healed Lara back to full health",
})

local matches = trx.strings.fuzzy_match("wolf", {
  { key = "wolf", value = trx.catalog.objects.WOLF },
  { key = "bear", value = trx.catalog.objects.BEAR },
})
local best = matches[1]

trx.items[12]:on_activate(function(item)
  trx.log.info("the item was activated")
end)

trx.items[12]:on_destroy(function(item)
  trx.log.info("the item was removed")
end)

trx.items[12]:on_enter_sim(function(item)
  trx.log.info("the item started running")
end)

trx.items[12]:on_enter_world(function(item)
  trx.log.info("the item entered the world")
end)

trx.items[12]:on_finish(function(item)
  trx.log.info("the item finished its run")
end)

trx.items[12]:on_hit(function(item, damage)
  trx.log.info("the item lost " .. damage .. " hit points")
end)

trx.items[12]:on_kill(function(item)
  trx.log.info("the item is down")
end)

trx.items[12]:on_leave_sim(function(item)
  trx.log.info("the item stopped running")
end)

trx.items[12]:on_leave_world(function(item)
  trx.log.info("the item left the world")
end)

trx.items[12]:on_trigger(function(item, trigger)
  trx.log.info("triggered with mask " .. trigger.mask)
end)

local hurt = trx.items.query:where(function(id, item)
  return item.hit_points < 10
end)
